<?php
/**
 * Script de Padronização e Sincronização Autônoma de Imagens Sem Fundo e SEO para Variações.
 *
 * Funciona de forma idempotente em Local e em Produção.
 * Contém os binários WebP transparentes dos esquemas técnicos e variações embutidos,
 * garantindo provisionamento automático de arquivos físicos caso não existam no servidor.
 *
 * Uso via WP-CLI:
 *   Dry-run: wp eval-file scripts/maintenance/uonix-sync-variation-images.php
 *   Aplicar: wp eval-file scripts/maintenance/uonix-sync-variation-images.php apply
 */

if ( ! defined( "ABSPATH" ) ) {
    exit( "Este script deve ser executado via WP-CLI (wp eval-file).\n" );
}

$is_apply = false;
if ( isset( $args ) && is_array( $args ) ) {
    foreach ( $args as $a ) {
        if ( "apply" === strtolower( trim( (string) $a ) ) ) {
            $is_apply = true;
        }
    }
}

$mode = $is_apply ? "APLICAR MUDANÇAS" : "SIMULAÇÃO (dry-run)";
echo "========================================================================\n";
echo "🖼️  UÔNIX: SINCRONIZAÇÃO DE IMAGENS E SEO DE VARIAÇÕES ($mode)\n";
echo "========================================================================\n\n";

global $wpdb;

$embedded_images = array(
    "sapatilha" => "",
    "esticador" => "",
    "grampo"    => "",
    "10g"       => "",
    "50g"       => "",
    "250g"      => ""
);

function uonix_get_or_create_media( $relative_file, $parent_id, $title, $alt, $base64_data, $is_apply ) {
    global $wpdb;

    $upload_dir = wp_upload_dir();
    $full_path = $upload_dir["basedir"] . "/" . $relative_file;

    // Se o arquivo físico não existe, recria a partir do Base64 embutido
    if ( ! file_exists( $full_path ) ) {
        if ( $is_apply && ! empty( $base64_data ) ) {
            $binary = base64_decode( $base64_data );
            $dir = dirname( $full_path );
            if ( ! file_exists( $dir ) ) {
                wp_mkdir_p( $dir );
            }
            file_put_contents( $full_path, $binary );
            echo "  📁 [DISCO] Arquivo físico gerado em $full_path (" . round( strlen( $binary ) / 1024, 1 ) . " KB)\n";
        } else {
            echo "  ⚠️ [DISCO] Arquivo não encontrado fisicamente: $full_path (será criado ao aplicar)\n";
        }
    }

    // Buscar anexo existente pelo meta _wp_attached_file
    $attachment_id = $wpdb->get_var( $wpdb->prepare(
        "SELECT post_id FROM {$wpdb->postmeta} WHERE meta_key = '_wp_attached_file' AND meta_value = %s LIMIT 1",
        $relative_file
    ) );

    if ( ! $attachment_id ) {
        $basename = basename( $relative_file );
        $attachment_id = $wpdb->get_var( $wpdb->prepare(
            "SELECT post_id FROM {$wpdb->postmeta} WHERE meta_key = '_wp_attached_file' AND meta_value LIKE %s LIMIT 1",
            "%" . $wpdb->esc_like( $basename )
        ) );
    }

    if ( ! $attachment_id ) {
        if ( $is_apply ) {
            if ( ! file_exists( $full_path ) ) {
                echo "  ❌ Impossível cadastrar mídia sem arquivo físico.\n";
                return 0;
            }
            $filetype = wp_check_filetype( $full_path, null );
            $attachment = array(
                "guid"           => $upload_dir["baseurl"] . "/" . $relative_file,
                "post_mime_type" => $filetype["type"],
                "post_title"     => $title,
                "post_content"   => "",
                "post_status"    => "inherit",
                "post_parent"    => $parent_id
            );
            $attachment_id = wp_insert_attachment( $attachment, $full_path, $parent_id );
            require_once( ABSPATH . "wp-admin/includes/image.php" );
            $attach_data = wp_generate_attachment_metadata( $attachment_id, $full_path );
            wp_update_attachment_metadata( $attachment_id, $attach_data );
            update_post_meta( $attachment_id, "_wp_attached_file", $relative_file );
            update_post_meta( $attachment_id, "_wp_attachment_image_alt", $alt );
            echo "  ✨ [CRIADO] Nova mídia ID $attachment_id para $relative_file\n";
        } else {
            echo "  ✨ [SIMULAÇÃO CRIAR] Criaria mídia WordPress para $relative_file\n";
            return 999999;
        }
    } else {
        if ( $is_apply ) {
            $current_post = get_post( $attachment_id );
            $current_alt = get_post_meta( $attachment_id, "_wp_attachment_image_alt", true );
            if ( $current_post && ( $current_post->post_title !== $title || $current_post->post_parent != $parent_id ) ) {
                wp_update_post( array(
                    "ID"          => $attachment_id,
                    "post_title"  => $title,
                    "post_parent" => $parent_id
                ) );
                echo "  🔄 [METADADOS] Atualizado título e parent para mídia ID $attachment_id\n";
            }
            if ( $current_alt !== $alt ) {
                update_post_meta( $attachment_id, "_wp_attachment_image_alt", $alt );
                echo "  🔄 [ALT] Atualizado Alt Text para mídia ID $attachment_id\n";
            }
        }
    }

    return intval( $attachment_id );
}

