}

if ( $prod_sapatilha ) {
    $parent_id = $prod_sapatilha->ID;
    $sapatilha_spec = array(
        "file"  => "2026/09/sapatilha-para-cabo-de-aco-esquema-tecnico-sem-fundo.webp",
        "title" => "Sapatilha para Cabo de Aço - Esquema Técnico de Dimensões - Uônix",
        "alt"   => "Esquema técnico e dimensões da sapatilha para cabo de aço Uônix",
        "b64"   => $embedded_images["sapatilha"]
    );

    $att_id = uonix_get_or_create_media( $sapatilha_spec["file"], $parent_id, $sapatilha_spec["title"], $sapatilha_spec["alt"], $sapatilha_spec["b64"], $is_apply );
    echo "  Mídia Esquema Técnico da Sapatilha ID: $att_id\n";

    $sapatilha_obj = wc_get_product( $parent_id );
    $variations = $sapatilha_obj ? $sapatilha_obj->get_children() : array();

    foreach ( $variations as $var_id ) {
        $curr_thumb = get_post_thumbnail_id( $var_id );
        echo "  Var #$var_id: Thumb atual = $curr_thumb -> Novo = $att_id\n";
        if ( $is_apply && $att_id > 0 && $curr_thumb != $att_id ) {
            set_post_thumbnail( $var_id, intval( $att_id ) );
            echo "    ✅ Variação #$var_id atualizada para mídia ID $att_id\n";
        }
    }

    if ( $is_apply && $att_id > 0 ) {
        update_post_meta( $parent_id, "_uonix_vtst_diagram_image_id", intval( $att_id ) );
        echo "  ✅ Diagrama técnico atualizado para mídia ID $att_id\n";
    }
}

